import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, color, smoothstep, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight } = ctx.THREE;

  const root = new Group();
  root.name = 'filmstrip-carousel';

  const disposables = [];
  const timelines = [];
  const primHandles = [];
  const clonedTextures = [];

  // ---------- palette ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {};
  const C_BG0 = colors.gradientStops?.[0]?.hex ?? '#0b0b10';
  const C_BG1 = colors.gradientStops?.[1]?.hex ?? '#12121a';
  const C_SURFACE = colors.surface ?? '#14141a';
  const C_INK = colors.ink ?? '#16161d';
  const C_PAPER = colors.paper ?? '#e8ecf2';
  const C_ACCENT = colors.accent ?? '#ff2a38';

  const headlineItem = items.find((i) => i.role === 'headline');
  const bodyItem = items.find((i) => i.role === 'body');
  const captionItems = items.filter((i) => i.role === 'caption');

  // ---------- backdrop stage (7x6 @ z=-2.5, vertical gradient) ----------
  const backMat = new MeshBasicNodeMaterial();
  backMat.colorNode = mix(color(C_BG1), color(C_BG0), smoothstep(0.0, 1.0, uv().y));
  const backGeo = new PlaneGeometry(7.4, 6.2);
  const backdrop = new Mesh(backGeo, backMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backGeo, backMat);

  // mid-depth surface band behind the strip (depth plane #2)
  const bandMat = new MeshStandardNodeMaterial({
    color: C_SURFACE,
    roughness: 0.6,
    metalness: 0.35,
  });
  const bandGeo = new PlaneGeometry(7.0, 1.75);
  const band = new Mesh(bandGeo, bandMat);
  band.position.set(0, 0, -1.5);
  root.add(band);
  disposables.push(bandGeo, bandMat);

  // ---------- node-local lights (scene gives ambient 0.6 + key 1.2) ----------
  const rim = new DirectionalLight(0xe8ecf2, 0.8);
  rim.position.set(-3, 2, -2);
  root.add(rim);
  const accentRim = new DirectionalLight(0xff2a38, 0.5);
  accentRim.position.set(4, -1, -1.5);
  root.add(accentRim);

  // ---------- filmstrip ----------
  const PITCH = 1.85;
  const CARD_W = 1.6;
  const CARD_H = 1.0;
  const BEVEL = 0.025;
  const N = 5;
  const STRIP_TILT = -18 * (Math.PI / 180);

  const strip = new Group();
  strip.rotation.y = STRIP_TILT;
  strip.position.set(0.25, 0, -0.25);
  root.add(strip);

  const slider = new Group();
  strip.add(slider);

  // distinct placeholder plates + distinct crops of the base texture (no echo)
  const plateTints = ['#8d939c', '#6e747d', '#a0a6ae', '#5c626b', '#7b818a'];
  const crops = [
    { ox: 0.0, oy: 0.4, r: 0.55 },
    { ox: 0.42, oy: 0.02, r: 0.5 },
    { ox: 0.18, oy: 0.22, r: 0.62 },
    { ox: 0.48, oy: 0.44, r: 0.48 },
    { ox: 0.05, oy: 0.05, r: 0.58 },
  ];

  const cards = [];
  const frameGeo = new BoxGeometry(CARD_W + BEVEL * 2, CARD_H + BEVEL * 2, 0.06);
  const photoGeo = new PlaneGeometry(CARD_W, CARD_H);
  const barGeo = new BoxGeometry(CARD_W, 0.035, 0.02);
  disposables.push(frameGeo, photoGeo, barGeo);

  for (let i = 0; i < N; i++) {
    const cardGroup = new Group();
    cardGroup.position.x = (i - 2) * PITCH;
    slider.add(cardGroup);

    const frameMat = new MeshStandardNodeMaterial({
      color: C_INK,
      roughness: 0.5,
      metalness: 0.55,
      transparent: true,
      opacity: 1,
    });
    const frame = new Mesh(frameGeo, frameMat);
    cardGroup.add(frame);
    disposables.push(frameMat);

    const photoMat = new MeshPhysicalNodeMaterial({
      color: plateTints[i],
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      transparent: true,
      opacity: 1,
    });
    const photo = new Mesh(photoGeo, photoMat);
    photo.position.z = 0.035;
    cardGroup.add(photo);
    disposables.push(photoMat);

    // accent underline bar (focused only) — the single brightest element
    const barMat = new MeshStandardNodeMaterial({
      color: C_ACCENT,
      emissive: C_ACCENT,
      emissiveIntensity: 1.3,
      roughness: 0.6,
      metalness: 0.1,
      transparent: true,
      opacity: 0,
    });
    const bar = new Mesh(barGeo, barMat);
    bar.position.set(0, -(CARD_H / 2) - 0.125, 0.05);
    cardGroup.add(bar);
    disposables.push(barMat);

    // caption below focused card
    let caption = null;
    const capItem = captionItems[i];
    if (capItem) {
      caption = ctx.fontAtlas.createText(String(capItem.text), {
        fontSize: capItem.typography?.fontSize ?? 18,
        color: C_PAPER,
        align: 'center',
        letterSpacingPx: 1.5,
      });
      caption.position.set(0, -(CARD_H / 2) - 0.3, 0.05);
      caption.visible = false;
      cardGroup.add(caption);
    }

    cards.push({ group: cardGroup, frameMat, photoMat, barMat, caption, photo });
  }

  // load base texture, apply distinct crop per card
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      for (let i = 0; i < N; i++) {
        const t = tex.clone();
        const c = crops[i];
        t.repeat.set(c.r, c.r);
        t.offset.set(c.ox, c.oy);
        t.needsUpdate = true;
        cards[i].photoMat.map = t;
        cards[i].photoMat.color.set('#ffffff');
        cards[i].photoMat.needsUpdate = true;
        clonedTextures.push(t);
        cards[i].baseOffsetX = c.ox;
      }
    });
  }

  // ---------- headline / body ----------
  if (headlineItem) {
    const h = ctx.fontAtlas.createText(String(headlineItem.text), {
      fontSize: headlineItem.typography?.fontSize ?? 68,
      color: C_PAPER,
      align: 'left',
    });
    h.position.set(-2.6, 1.5, 0);
    root.add(h);

    // foreground accent rule under headline (depth plane #3)
    const ruleMat = new MeshStandardNodeMaterial({
      color: C_ACCENT,
      emissive: C_ACCENT,
      emissiveIntensity: 0.9,
      roughness: 0.6,
      metalness: 0.1,
    });
    const ruleGeo = new BoxGeometry(0.75, 0.025, 0.02);
    const rule = new Mesh(ruleGeo, ruleMat);
    rule.position.set(-2.25, 1.25, 0.15);
    root.add(rule);
    disposables.push(ruleGeo, ruleMat);
  }
  if (bodyItem) {
    const b = ctx.fontAtlas.createText(String(bodyItem.text), {
      fontSize: bodyItem.typography?.fontSize ?? 26,
      color: C_PAPER,
      align: 'left',
    });
    b.position.set(-2.6, -1.5, 0);
    root.add(b);
  }

  // ---------- carousel state / focus logic ----------
  const state = { offset: 0, uvShift: 0 };
  let focusIndex = 2;

  function applyDistances(offset) {
    for (let i = 0; i < N; i++) {
      const lx = (i - 2) * PITCH;
      const d = Math.abs(lx - offset) / PITCH;
      const s = 1 - 0.08 * Math.min(1, d);
      const card = cards[i];
      card.group.scale.setScalar(i === focusIndex ? Math.max(s, card.group.scale.x) : s);
      const op = Math.max(0.55, 1 - 0.225 * d);
      card.frameMat.opacity = op;
      card.photoMat.opacity = op;
      // internal texture parallax counter-shift
      if (card.photoMat.map && typeof card.baseOffsetX === 'number') {
        card.photoMat.map.offset.x = card.baseOffsetX + state.uvShift;
      }
    }
  }

  function setFocus(idx) {
    idx = Math.max(0, Math.min(N - 1, idx));
    if (idx === focusIndex) return;
    const prev = cards[focusIndex];
    focusIndex = idx;
    const next = cards[idx];

    const tl = gsap.timeline();
    tl.to(prev.group.rotation, { y: 0, duration: 0.9, ease: 'power4.out' }, 0);
    tl.to(prev.group.scale, { x: 0.92, y: 0.92, z: 0.92, duration: 0.9, ease: 'power4.out' }, 0);
    tl.to(prev.barMat, { opacity: 0, duration: 0.3, ease: 'power2.out' }, 0);
    tl.call(() => { if (prev.caption) prev.caption.visible = false; }, null, 0.15);

    tl.to(next.group.rotation, { y: -STRIP_TILT, duration: 0.9, ease: 'power4.out' }, 0);
    tl.to(next.group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.45, ease: 'power2.out' }, 0);
    tl.to(next.group.scale, { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power4.out' }, 0.45);
    tl.to(next.barMat, { opacity: 1, duration: 0.4, ease: 'power2.out' }, 0.25);
    tl.call(() => { if (next.caption) next.caption.visible = true; }, null, 0.3);
    timelines.push(tl);
  }

  // initial focus: card at x=0 faces camera dead-on
  const c0 = cards[focusIndex];
  c0.group.rotation.y = -STRIP_TILT;
  c0.group.scale.setScalar(1);
  c0.barMat.opacity = 1;
  if (c0.caption) c0.caption.visible = true;
  applyDistances(0);

  // ---------- scroll: translate strip, counter-shift UVs, snap on end ----------
  let snapCall = null;
  let snapTween = null;
  const MAX_OFFSET = 2 * PITCH;

  function snapToNearest() {
    const idx = Math.max(0, Math.min(N - 1, Math.round(state.offset / PITCH) + 2));
    const target = (idx - 2) * PITCH;
    setFocus(idx);
    if (snapTween) snapTween.kill();
    // weighted-settle: 1.04 overshoot -> 1.0
    const overshoot = target + (target - state.offset) * 0.04;
    const tl = gsap.timeline();
    tl.to(state, {
      offset: overshoot,
      uvShift: 0,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => { slider.position.x = -state.offset; applyDistances(state.offset); },
    });
    tl.to(state, {
      offset: target,
      duration: 0.4,
      ease: 'power4.out',
      onUpdate: () => { slider.position.x = -state.offset; applyDistances(state.offset); },
    });
    snapTween = tl;
    timelines.push(tl);
  }

  function onScroll(e) {
    const delta = (e && (e.deltaY ?? e.delta ?? e.dy)) || 0;
    state.offset = Math.max(-MAX_OFFSET, Math.min(MAX_OFFSET, state.offset + delta * 0.5 * 0.0035));
    state.uvShift = Math.max(-0.04, Math.min(0.04, delta * 0.0004));
    slider.position.x = -state.offset;
    applyDistances(state.offset);
    if (snapCall) snapCall.kill();
    snapCall = gsap.delayedCall(0.18, snapToNearest);
  }

  root.userData.handlers = {
    scroll: onScroll,
    wheel: onScroll,
  };

  // ---------- entrance: rise-in with weight ----------
  strip.position.y = -0.4;
  const enter = gsap.timeline();
  enter.to(strip.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  timelines.push(enter);

  // ---------- cinematic primitives ----------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (fn) primHandles.push(fn(strip, p.params ?? {}));
  }

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    if (snapCall) snapCall.kill();
    if (snapTween) snapTween.kill();
    for (const h of primHandles) h && h.cleanup && h.cleanup();
    for (const t of clonedTextures) t.dispose();
    for (const d of disposables) d.dispose && d.dispose();
  };

  return root;
}
